            String userHeader, String reason, String batch, boolean dryRun) throws ClaimStatusException, ClerkLimitException, ProofRequiredException {
        if (dryRun && !"settle".equals(action)) {
            throw new ClaimStatusException("Only a settle can be checked.");
        }
        String user = AuditUser.decode(userHeader);
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim in a closed period cannot change status.");
        }
        String role = roles.roleOf(claim.getSheetId(), user);
        if (("open".equals(action) || "settle".equals(action) || "void".equals(action)) && !sheet.allows(action, role)) {
            throw new ClerkLimitException("A " + role + " cannot " + action + " a claim.");
        }
        if ("open".equals(action) && claim.getStatus().after(action) != null) {
            // Lock the sheet first (taking a number locks it), then re-read the claim so a concurrent open is seen.
            boolean perPeriod = sheet.periodNumberingOn();
            if (perPeriod) {
                repository.lockSheet(claim.getSheetId());
            } else {
                repository.takeNextNumber(claim.getSheetId());
            }
            entityManager.refresh(claim);
            ClaimStatus next = check(claim, action);
            BigDecimal noteThreshold = sheet.noteThresholdOn(claim.getDate());
            if (noteThreshold != null && (claim.getNote() == null || claim.getNote().isBlank())) {
                BigDecimal due = people.findById(claim.getPersonId())
                        .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
                                grades.gradesOf(p), sheet).due(claim))
                        .orElse(null);
                if (due != null && due.compareTo(noteThreshold) > 0) {
                    throw new ClaimStatusException("A claim whose due is above the note threshold needs a note to be opened.");
                }
            }
            if (perPeriod) {
                String prefix = periods.findBySheetIdOrderByFromDateAscIdAsc(claim.getSheetId()).stream()
                        .filter(p -> p.contains(claim.getDueBy())).map(Period::getName).findFirst().orElse(null);
                String seq = prefix == null ? "X" : "P:" + prefix;
                claim.setNumber((prefix == null ? "X" : prefix) + "-" + repository.takeNextInSequence(claim.getSheetId(), seq));
            } else {
                claim.setNumber(String.valueOf(repository.lastNumber(claim.getSheetId())));
            }
            claim.setStatus(next);
            claim.setOpenedBy(user);
        } else {
            ClaimStatus next = check(claim, action);
            boolean steward = Role.STEWARD.equals(role);
            if (("approve".equals(action) || "reject".equals(action)) && !steward) {
                throw new ClerkLimitException("Only a steward can approve or reject a pending claim.");
            }
            if ("void".equals(action) && claim.getStatus() == ClaimStatus.SETTLED) {
                if (!steward) {
                    throw new ClerkLimitException("Only a steward can void a settled claim.");
                }
                LocalDate settled = log.settledOn(claim);
                if (settled == null || sheet.getToday().isAfter(settled.plusDays(VOID_DAYS))) {
                    throw new ClaimStatusException("A settled claim can be voided only within " + VOID_DAYS + " days of its settlement.");
    public Split apply(@Val Claim claim, @Val Sheet sheet, ClaimRepository repository, EntityManager entityManager,
            PeriodRepository periods, PersonRepository people, PersonGradeRepository grades, RateRepository rates,
            ClaimLogRepository log, HolidayRepository holidays,
            @RequestHeader(name = "X-User", required = false) String userHeader,
            @RequestParam(name = "amount", required = false) String amountParam) throws ClaimStatusException {
        String user = AuditUser.decode(userHeader);
        String amountField = amountParam == null ? "" : amountParam.trim();
        if (!AMOUNT.matcher(amountField).matches()) {
            throw new ClaimStatusException("The amount to split off must be a number with up to two decimals.");
        }
        BigDecimal amount = new BigDecimal(amountField).setScale(2);
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim in a closed period cannot be split.");
        }
        // Lock the sheet first (taking a number locks it), then re-read the claim so a concurrent change is seen.
        boolean perPeriod = sheet.periodNumberingOn();
        if (perPeriod) {
            repository.lockSheet(claim.getSheetId());
        } else {
            repository.takeNextNumber(claim.getSheetId());
        }
        entityManager.refresh(claim);
        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheet.getToday())) {
            throw new ClaimStatusException("Only an OPEN claim that is not deferred can be split.");
        }
        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
            throw new ClaimStatusException("The amount to split off must be more than 0.00 and less than the claim's.");
        }
        int terms = people.findById(claim.getPersonId())
                .map(p -> sheet.termsFor(p.getTerms(), grades.gradesOf(p).on(claim.getDate()), claim.getDate())).orElse(0);
        LocalDate dueBy = holidays.dueBy(claim.getSheetId(), claim.getDate(), terms);
        String number;
        if (perPeriod) {
            String prefix = periods.findBySheetIdOrderByFromDateAscIdAsc(claim.getSheetId()).stream()
                    .filter(p -> p.contains(dueBy)).map(Period::getName).findFirst().orElse(null);
            String seq = prefix == null ? "X" : "P:" + prefix;
            number = (prefix == null ? "X" : prefix) + "-" + repository.takeNextInSequence(claim.getSheetId(), seq);
        } else {
            number = String.valueOf(repository.lastNumber(claim.getSheetId()));
        }
        claim.setAmount(claim.getAmount().subtract(amount));
        claim.bind(false, null);
        repository.saveAndFlush(claim);

        Claim made = new Claim(claim.getSheetId(), claim.getPersonId(), amount, claim.getDate(), claim.getNote(), null);
        made.setStatus(ClaimStatus.OPEN);
        made.setNumber(number);
        made.setOpenedBy(user);
        made.setSplitFrom(claim.getNumber());
        made.setTags(claim.getTags());
        made.fixDue(claim.getDate(), terms, holidays.datesOf(claim.getSheetId()));
        made.setLateEntry(periods.isSoftClosedOn(claim.getSheetId(), dueBy));
        made = repository.saveAndFlush(made);
        entityManager.refresh(made);
        ClaimRules.log(made, sheet, log, people, rates, grades, user);
        return new Split(made);
    }
}
        }
        LocalDate date;
        try {
            date = LocalDate.parse(dateParam == null ? "" : dateParam.trim());
        } catch (DateTimeParseException e) {
            throw new ClaimStatusException("Not a date: " + dateParam);
        }
        boolean perPeriod = sheet.periodNumberingOn();
        if (perPeriod) {
            // Lock the sheet first (taking a number locks it), then re-read the claim so a concurrent change is seen.
            repository.lockSheet(claim.getSheetId());
            entityManager.refresh(claim);
        }
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be re-dated.");
        }
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim cannot be re-dated while its due-by is in a closed period.");
        }
        if (people.findById(claim.getPersonId()).map(p -> p.retiredOn(date)).orElse(false)) {
            throw new ClaimStatusException("No claim can be dated after the person's retirement date.");
        }
        LocalDate old = claim.getDate();
        claim.setDate(date);
        repository.saveAndFlush(claim);
        return new Redated(old, date);
    }

}

